import json,re
d=json.load(open('products/services/software-renewals/raw/fts-awards-2025-03-03.json'))
def walk(o,p=''):
  if isinstance(o,dict):
    for k,v in o.items(): yield from walk(v,p+'.'+k)
  elif isinstance(o,list):
    for i,v in enumerate(o): yield from walk(v,p+'[%d]'%i)
  else: yield p,o
rs=d.get('releases',[])
print('n',len(rs))
for r in rs:
  t=r.get('tender',{})
  cpvs=[v for p,v in walk(t) if p.endswith('classification.id') or (p.endswith('.id') and 'Classifications' in p)]
  ends=[(p,v) for p,v in walk(r) if p.endswith('endDate')]
  sw=any(str(c).startswith(('72','48')) for c in cpvs)
  print(r['id'],'|',r.get('buyer',{}).get('name'),'|',t.get('title','')[:90],'| sw' if sw else '','| ends',ends[:3])
